"""Readers for the Markdown and reStructuredText used by the reporting service."""
import re
import string
from html import unescape

API_VERSION = [1, 23, 1, 2]


def node(kind, *content):
    result = {'t': kind}
    if content:
        result['c'] = content[0]
    return result


def attr(identifier='', classes=None, pairs=None):
    return [identifier, classes or [], pairs or []]


def text_of(inlines):
    result = []
    for inline in inlines:
        kind, content = inline['t'], inline.get('c')
        if kind in ('Space', 'SoftBreak', 'LineBreak'):
            result.append(' ')
        elif kind == 'Str':
            result.append(content)
        elif kind == 'Code':
            result.append(content[1])
        elif kind in ('Emph', 'Strong', 'Strikeout'):
            result.append(text_of(content))
        elif kind in ('Link', 'Image', 'Quoted'):
            result.append(text_of(content[1]))
    return ''.join(result)


def indented(lines, start, minimum=1):
    end = start
    while end < len(lines):
        line = lines[end]
        if line.strip() and len(line) - len(line.lstrip()) < minimum:
            break
        end += 1
    body = lines[start:end]
    margin = min((len(line) - len(line.lstrip()) for line in body if line.strip()), default=0)
    return [line[margin:] for line in body], end


def table(columns, header, body, caption, widths=()):
    specs = [[node('Align' + alignment), node('ColWidth', widths[i]) if i < len(widths)
              else node('ColWidthDefault')] for i, alignment in enumerate(columns)]

    def rows(data):
        return [[attr(), [[attr(), node('AlignDefault'), 1, 1, cell] for cell in row]]
                for row in data]

    return node('Table', [attr(), [None, caption], specs, [attr(), rows(header)],
                          [[attr(), 0, [], rows(body)]], [attr(), []]])


MD_INLINE = re.compile(
    r'(?P<escape>\\[\x21-\x2f\x3a-\x40\x5b-\x60\x7b-\x7e])|(?P<hard> {2,}\n|\\\n)|'
    r'(?P<note>\[\^[^\]\n]+\])|(?P<inline_note>\^\[[^\]\n]+\])|'
    r'(?P<link>!?\[[^\]\n]*\]\((?:[^()\n]|\([^()\n]*\))*\))|'
    r'(?P<ref>!?\[[^\]\n]+\](?:\[[^\]\n]*\])?)|'
    r'(?P<autolink><(?:https?://|mailto:)[^ >]+>|<[\w.+-]+@[\w.-]+>)|'
    r'(?P<raw><!--.*?-->|</?[A-Za-z][^>]*>)|(?P<code>(?P<ticks>`+)(?!`).+?(?<!`)(?P=ticks)(?!`))|'
    r'(?P<strong>\*\*(?=\S).+?\*\*|__(?=\S).+?__)|'
    r'(?P<emph>\*(?=\S).+?\*|(?<!\w)_(?=\S).+?_(?!\w))|(?P<strike>~~(?=\S).+?~~)|'
    r'(?P<quote>"(?=\S)[^"\n]+"|(?<!\w)\'(?=\S)[^\'\n]+\'(?!\w))|'
    r'(?P<entity>&(?:#[xX]?[a-fA-F0-9]+|[A-Za-z][A-Za-z0-9]+);)|(?P<space>[^\S\n]+|\n)')
RST_INLINE = re.compile(
    r'(?P<escape>\\.)|(?P<note>\[(?:\d+|\#[^\]\s]*|\*)\]_)|'
    r'(?P<link>`[^`\n]+`__?)|(?P<ref>\b[\w][\w.\-:+]*?__(?!\w)|\b[\w][\w.\-:+]*?_(?!\w))|'
    r'(?P<url>https?://[^\s<>]+[^\s<>.,;:!?])|(?P<code>``.+?``)|'
    r'(?P<strong>\*\*(?=\S).+?\*\*)|(?P<emph>\*(?=\S).+?\*)|(?P<space>[^\S\n]+|\n)')


class Reader:
    def __init__(self, fmt, extensions):
        self.rst = fmt == 'rst'
        self.extensions = extensions
        self.notes = {}
        self.note_positions = {'#': 0, '*': 0}
        self.resolving_notes = set()
        self.references = {}
        self.heading_styles = []
        self.identifiers = set()
        self.missing = []
        self.metadata = {}

    def inline(self, text):
        text = text.strip()
        pattern = RST_INLINE if self.rst else MD_INLINE
        inlines = []
        pending = []
        cursor = 0

        def flush():
            if pending:
                value = ''.join(pending)
                if not self.rst and self.extensions.get('smart', True):
                    value = value.replace('---', '—').replace('--', '–').replace('...', '…')
                    value = re.sub(r"(?<=\w)'(?=\w)", '’', value)
                inlines.append(node('Str', value))
                pending.clear()

        for match in pattern.finditer(text):
            kind, value = match.lastgroup, match[0]
            if cursor < match.start():
                pending.append(text[cursor:match.start()])
            cursor = match.end()
            converted = None
            if kind == 'escape':
                pending.append(value[1:])
                continue
            if kind == 'entity':
                pending.append(unescape(value))
                continue
            if kind == 'space':
                converted = node('SoftBreak' if value == '\n' else 'Space')
            elif kind == 'hard':
                converted = node('LineBreak')
            elif kind in ('strong', 'emph', 'strike'):
                size = 1 if kind == 'emph' else 2
                converted = node({'emph': 'Emph', 'strong': 'Strong', 'strike': 'Strikeout'}[kind],
                                 self.inline(value[size:-size]))
            elif kind == 'quote' and self.extensions.get('smart', True):
                converted = node('Quoted', [node('DoubleQuote' if value[0] == '"' else 'SingleQuote'),
                                            self.inline(value[1:-1])])
            elif kind == 'code':
                size = 2 if self.rst else len(match['ticks'])
                converted = node('Code', [attr(), value[size:-size].strip().replace('\n', ' ')])
            elif kind == 'note':
                key = value[1:-2] if self.rst else value[2:-1]
                if key in self.notes and key not in self.resolving_notes:
                    if self.rst and inlines and not pending and inlines[-1]['t'] == 'Space':
                        inlines.pop()
                    self.resolving_notes.add(key)
                    if self.rst and key in self.note_positions:
                        position = self.note_positions[key]
                        self.note_positions[key] += 1
                        bodies = self.notes[key]
                        blocks = self.blocks(bodies[position]) if position < len(bodies) else []
                    else:
                        blocks = self.blocks(self.notes[key])
                    self.resolving_notes.remove(key)
                    converted = node('Note', blocks)
                elif self.rst:
                    if inlines and not pending and inlines[-1]['t'] == 'Space':
                        inlines.pop()
                    self.missing.append(key)
                    converted = node('Link', [attr(), [node('Str', key)], ['##NOTE##' + key, '']])
            elif kind == 'inline_note':
                converted = node('Note', [node('Para', self.inline(value[2:-1]))])
            elif kind in ('url', 'autolink'):
                target = value.strip('<>')
                label = target.removeprefix('mailto:')
                if '@' in target and ':' not in target:
                    target = 'mailto:' + target
                converted = node('Link', [attr(), [node('Str', label)], [target, '']])
            elif kind == 'raw':
                converted = node('RawInline', ['html', value])
            elif kind in ('link', 'ref'):
                converted = self.link(kind, value)
            if converted is None:
                pending.append(value)
            else:
                flush()
                if converted['t'] != 'Space' or not inlines or inlines[-1]['t'] not in ('Space', 'SoftBreak', 'LineBreak'):
                    inlines.append(converted)
        pending.append(text[cursor:])
        # Avoid appending an empty Str after a final inline element.
        if any(pending):
            flush()
        return inlines

    def link(self, kind, value):
        if self.rst:
            label = value.rstrip('_').strip('`')
            explicit = re.fullmatch(r'(.*?)\s*<([^>]+)>', label)
            if explicit:
                label, target = explicit.groups()
                label = label or target
            else:
                target = self.references.get(label.casefold())
                if target is None:
                    self.missing.append(label)
                    target = ''
            return node('Link', [attr(), self.inline(label), [target, '']])
        if kind == 'link':
            label, target = value.removeprefix('!')[1:-1].split('](', 1)
            parts = re.fullmatch(r'\s*(<[^>]*>|\S*?)(?:\s+["\'](.*)["\'])?\s*', target)
            if not parts:
                return None
            target, title = parts.groups()
            destination = [unescape(target.strip('<>')).replace(' ', '%20'), title or '']
        else:
            label, _, key = value.removeprefix('!')[1:-1].partition('][')
            destination = self.references.get((key or label).casefold())
            if destination is None:
                return None
        return node('Image' if value.startswith('!') else 'Link', [attr(), self.inline(label), destination])

    def heading(self, level, text):
        attributes = attr()
        if not self.rst and (match := re.search(r'\s+\{([^{}]+)\}$', text)):
            attributes = parse_attributes(match[1])
            text = text[:match.start()]
        inlines = self.inline(text)
        if not attributes[0] and self.extensions.get('auto_identifiers', True):
            identifier = re.sub(r'[^\w .-]', '', text_of(inlines).lower()).replace(' ', '-')
            identifier = next((identifier[i:] for i, char in enumerate(identifier) if char.isalpha()), 'section')
            candidate = identifier
            suffix = 1
            while candidate in self.identifiers:
                candidate = f'{identifier}-{suffix}'
                suffix += 1
            attributes[0] = candidate
        self.identifiers.add(attributes[0])
        return node('Header', [level, attributes, inlines])

    def read(self, text):
        lines = text.expandtabs(4).splitlines()
        if not self.rst and lines and lines[0] == '---' and self.extensions.get('yaml_metadata_block', True):
            end = next((i for i in range(1, len(lines)) if lines[i] in ('---', '...')), None)
            if end is not None:
                entries = [re.fullmatch(r'([\w-]+):\s*(.*)', line) for line in lines[1:end] if line.strip()]
                if entries and all(entries):
                    self.metadata.update((entry[1], self.meta_value(entry[2])) for entry in entries)
                    lines = lines[end + 1:]
        return self.blocks(self.definitions(lines))

    def meta_value(self, value):
        if value.lower() in ('true', 'false'):
            return node('MetaBool', value.lower() == 'true')
        if value.startswith('[') and value.endswith(']'):
            return node('MetaList', [self.meta_value(item.strip()) for item in value[1:-1].split(',') if item.strip()])
        if len(value) >= 2 and value[0] == value[-1] in ('"', "'"):
            value = value[1:-1]
        return node('MetaInlines', self.inline(value))

    def definitions(self, lines):
        clean = []
        i = 0
        fence = None
        while i < len(lines):
            line = lines[i]
            i += 1
            if not self.rst and (marker := re.match(r'^ {0,3}(`{3,}|~{3,})(.*)', line)):
                if fence is None:
                    fence = marker[1]
                elif marker[1].startswith(fence) and not marker[2].strip():
                    fence = None
                clean.append(line)
                continue
            if fence:
                clean.append(line)
                continue
            note = re.match(r'^\.\. \[([^]]+)\]\s*(.*)' if self.rst else r'^\[\^([^]]+)\]:\s*(.*)', line)
            if note and (self.rst or self.extensions.get('footnotes', True)):
                rest, i = indented(lines, i, 1 if self.rst else 4)
                body = ([note[2]] if note[2] else []) + rest
                if self.rst and note[1] in self.note_positions:
                    self.notes.setdefault(note[1], []).append(body)
                else:
                    self.notes[note[1]] = body
                clean.append('')
                continue
            if self.rst and (ref := re.match(r'^\.\. _(.+?):\s*(.+)$', line)):
                self.references[ref[1].strip('`').casefold()] = ref[2]
                clean.append('')
                continue
            if not self.rst and (ref := re.fullmatch(r' {0,3}\[([^]]+)\]:\s*(\S+)(?:\s+["\'](.*)["\'])?\s*', line)):
                self.references[ref[1].casefold()] = [ref[2].strip('<>'), ref[3] or '']
                clean.append('')
                continue
            clean.append(line)
        return clean

    def blocks(self, lines):
        blocks = []
        i = 0
        while i < len(lines):
            line = lines[i]
            if not line.strip():
                i += 1
                continue
            special = self.rst_block(lines, i) if self.rst else self.markdown_block(lines, i)
            if special is not None:
                i, new = special
                blocks.extend(new)
                continue
            if marker := list_marker(line):
                i, block = self.read_list(lines, i, marker)
                blocks.append(block)
                continue
            end = i + 1
            while end < len(lines) and lines[end].strip() and not self.interrupts(lines[end]):
                if self.rst and lines[end].startswith(' ') and lines[end - 1].endswith('::'):
                    break
                end += 1
            paragraph = '\n'.join(lines[i:end]).strip()
            i = end
            if self.rst and paragraph.endswith('::'):
                start = i
                while start < len(lines) and not lines[start].strip():
                    start += 1
                if start < len(lines) and lines[start].startswith(' '):
                    body, i = indented(lines, start)
                    if paragraph != '::':
                        paragraph = paragraph[:-1].rstrip(':') if paragraph.endswith(' ::') else paragraph[:-1]
                        blocks.append(node('Para', self.inline(paragraph)))
                    blocks.append(node('CodeBlock', [attr(), '\n'.join(body).rstrip('\n')]))
                    continue
            blocks.append(node('Para', self.inline(paragraph)))
        return blocks

    def interrupts(self, line):
        if self.rst:
            return line.startswith('.. ') or bool(list_marker(line))
        return bool(re.match(r'^ {0,3}(?:#{1,6}(?:\s|$)|`{3,}|~{3,}|>)', line))

    def rst_block(self, lines, i):
        line = lines[i]
        if i + 2 < len(lines) and adornment(line, lines[i + 1]) and lines[i + 2] == line:
            return i + 3, [self.heading(self.rst_level((line[0], True)), lines[i + 1])]
        if i + 1 < len(lines) and adornment(lines[i + 1], line):
            return i + 2, [self.heading(self.rst_level((lines[i + 1][0], False)), line)]
        if line.startswith('.. ') or line == '..':
            body, end = indented(lines, i + 1)
            directive = re.match(r'^\.\. ([\w-]+)::\s*(.*)', line)
            if not directive:
                return end, []
            name, argument = directive.groups()
            return end, self.directive(name, argument, body)
        if len(line) >= 4 and adornment(line, 'text'):
            return i + 1, [node('HorizontalRule')]
        if line.startswith(' '):
            body, end = indented(lines, i)
            return end, [node('BlockQuote', self.blocks(body))]
        return None

    def rst_level(self, style):
        if style not in self.heading_styles:
            self.heading_styles.append(style)
        return self.heading_styles.index(style) + 1

    def directive(self, name, argument, body):
        options = {}
        while body and (option := re.match(r':([\w-]+):\s*(.*)', body[0])):
            options[option[1]] = option[2]
            body = body[1:]
        if name == 'list-table':
            return self.list_table(argument, body, options)
        if name in ('code', 'code-block', 'sourcecode'):
            return [node('CodeBlock', [attr(classes=argument.split()), '\n'.join(body).strip('\n')])]
        if name in ('note', 'warning', 'tip', 'important', 'caution', 'attention', 'danger', 'error', 'hint'):
            title = node('Div', [attr(classes=['title']), [node('Para', self.inline(name.title()))]])
            return [node('Div', [attr(classes=[name]), [title] + self.blocks(([argument] if argument else []) + body)])]
        if name == 'image':
            return [node('Para', [node('Image', [attr(), self.inline(options.get('alt', '')), [argument, '']])])]
        if name == 'rubric':
            return [node('Para', self.inline(argument))]
        return []

    def list_table(self, caption, body, options):
        rows = []
        for line in body:
            if match := re.match(r'^\*\s+-\s*(.*)$', line):
                rows.append([[match[1]]])
            elif rows and (match := re.match(r'^\s+-\s*(.*)$', line)):
                rows[-1].append([match[1]])
            elif rows:
                rows[-1][-1].append(line[4:] if line.startswith('    ') else line)
        if not rows:
            return []
        count = min(map(len, rows))
        header_rows = options.get('header-rows', '0')
        header_count = int(header_rows) if header_rows.isdecimal() else 0
        widths = options.get('widths', '').split()
        numbers = [int(width) for width in widths] if all(width.isdecimal() for width in widths) else []
        fractions = [value / sum(numbers) for value in numbers] if sum(numbers) else []

        def read_cell(lines):
            blocks = self.blocks(lines)
            if len(blocks) == 1 and blocks[0]['t'] == 'Para':
                blocks[0]['t'] = 'Plain'
            return blocks

        cells = [[read_cell(cell) for cell in row[:count]] for row in rows]
        return [table(['Default'] * count, cells[:header_count], cells[header_count:],
                      [node('Plain', self.inline(caption))] if caption else [], fractions)]

    def markdown_block(self, lines, i):
        line = lines[i]
        if match := re.match(r'^ {0,3}(#{1,6})(?:[ \t]+(.*)|$)', line):
            title = re.sub(r'\s+#+\s*$', '', match[2] or '')
            return i + 1, [self.heading(len(match[1]), title)]
        if i + 1 < len(lines) and re.fullmatch(r' {0,3}(=+|-+)\s*', lines[i + 1]):
            return i + 2, [self.heading(1 if '=' in lines[i + 1] else 2, line.strip())]
        if match := re.match(r'^ {0,3}(`{3,}|~{3,})\s*(.*)', line):
            end = i + 1
            while end < len(lines) and not re.fullmatch(r' {0,3}' + re.escape(match[1][0]) + '{' + str(len(match[1])) + r',}\s*', lines[end]):
                end += 1
            spec = match[2].strip()
            attrs = parse_attributes(spec[1:-1]) if spec.startswith('{') and spec.endswith('}') else attr(classes=spec.split()[:1])
            return min(end + 1, len(lines)), [node('CodeBlock', [attrs, '\n'.join(lines[i + 1:end])])]
        if self.extensions.get('pipe_tables', True):
            if parsed := self.pipe_table(lines, i):
                return parsed
        if re.fullmatch(r' {0,3}(?:(?:\*\s*){3,}|(?:-\s*){3,}|(?:_\s*){3,})', line):
            return i + 1, [node('HorizontalRule')]
        if line.startswith('    '):
            body, end = indented(lines, i, 4)
            return end, [node('CodeBlock', [attr(), '\n'.join(body).rstrip('\n')])]
        if line.lstrip().startswith('>'):
            end = i
            body = []
            while end < len(lines) and (quote := re.match(r'^ {0,3}> ?(.*)', lines[end])):
                body.append(quote[1])
                end += 1
            return end, [node('BlockQuote', self.blocks(body))]
        return None

    def pipe_table(self, lines, i):
        def split(line):
            return [part.strip() for part in re.split(r'(?<!\\)\|', line.strip().removeprefix('|').removesuffix('|'))]

        if i + 1 >= len(lines) or '|' not in lines[i + 1]:
            return None
        header, rules = split(lines[i]), split(lines[i + 1])
        if len(header) != len(rules) or not all(re.fullmatch(r':?-+:?', cell) for cell in rules):
            return None
        alignments = []
        for cell in rules:
            left, right = cell.startswith(':'), cell.endswith(':')
            alignments.append('Center' if left and right else 'Left' if left else 'Right' if right else 'Default')

        def cells(row):
            return [[node('Plain', self.inline(cell))] if cell else [] for cell in (row + [''] * len(rules))[:len(rules)]]

        end = i + 2
        body = []
        while end < len(lines) and '|' in lines[end] and lines[end].strip():
            body.append(cells(split(lines[end])))
            end += 1
        caption = []
        start = end + 1 if end < len(lines) and not lines[end].strip() else end
        if start < len(lines) and (match := re.match(r'^(?:Table)?:\s+(.+)', lines[start])):
            caption = [node('Plain', self.inline(match[1]))]
            end = start + 1
        return end, [table(alignments, [cells(header)], body, caption)]

    def read_list(self, lines, i, first):
        items = []
        ordered = first['number'] is not None
        loose = False
        while i < len(lines) and (marker := list_marker(lines[i])):
            if (marker['number'] is not None) != ordered or marker['indent'] != first['indent']:
                break
            body, end = indented(lines, i + 1, marker.start('text'))
            trailing_blank = bool(body and not body[-1].strip())
            while body and not body[-1].strip():
                body.pop()
            next_marker = list_marker(lines[end]) if end < len(lines) else None
            if trailing_blank and next_marker and (next_marker['number'] is not None) == ordered:
                loose = True
            if any(not line.strip() for line in body):
                loose = True
            items.append(self.blocks([marker['text']] + body))
            i = end
        if not loose:
            for item in items:
                if item and item[0]['t'] == 'Para':
                    item[0]['t'] = 'Plain'
        if ordered:
            delimiter = 'Period' if first['delimiter'] == '.' else 'OneParen'
            return i, node('OrderedList', [[int(first['number']), node('Decimal'), node(delimiter)], items])
        return i, node('BulletList', items)


def adornment(line, title):
    return bool(title.strip() and not title.startswith(' ') and line and line[0] in string.punctuation
                and len(line) >= len(title.rstrip()) and line == line[0] * len(line))


def list_marker(line):
    return re.match(r'^(?P<indent> {0,3})(?:[-+*]|(?P<number>\d+)(?P<delimiter>[.)]))\s+(?P<text>\S.*)', line)


def parse_attributes(spec):
    result = attr()
    for part in re.findall(r'[^\s=]+=(?:"[^"]*"|\'[^\']*\'|\S+)|\S+', spec):
        if part.startswith('#'):
            result[0] = part[1:]
        elif part.startswith('.'):
            result[1].append(part[1:])
        elif '=' in part:
            key, val = part.split('=', 1)
            result[2].append([key, val.strip('"\'')])
    return result

