"""Lexer and recursive-descent parser for the PHP constructs used by the station."""

import re
from collections import namedtuple

Token = namedtuple('Token', 'kind text line')

LEXER = re.compile(r'''(?P<space>\s+)|(?P<closing>\?>\r?\n?)|
    (?P<comment>/\*[\s\S]*?\*/|(?://|\#)(?:(?!\?>)[^\r\n])*)|
    (?P<string>"(?:\\[\s\S]|[^"\\])*"|'(?:\\[\s\S]|[^'\\])*')|
    (?P<var>\$[a-zA-Z_\x80-\uffff][\w]*)|
    (?P<name>[a-zA-Z_\x80-\uffff][\w]*)|
    (?P<number>0[xX][0-9a-fA-F_]+|0[bB][01_]+|0[oO][0-7_]+|
        (?:[0-9][0-9_]*(?:\.[0-9_]*)?|\.[0-9][0-9_]*)(?:[eE][+-]?[0-9][0-9_]*)?)|
    (?P<symbol>\?\?=|===|!==|<=>|\*\*|=>|->|::|\?\?|==|!=|<=|>=|&&|\|\||\+\+|--|[+\-*/%.]=|.)''', re.X)
OPENING = re.compile(r'<\?(?:php(?=\s|$)|=)', re.I)


class ParseError(Exception):
    def __init__(self, token, expected=None):
        self.line = token.line
        if token.kind == 'eof':
            found = 'end of file'
        elif token.kind == 'var':
            found = f'variable "{token.text}"'
        elif token.kind == 'name':
            found = f'identifier "{token.text}"'
        else:
            found = f'token "{token.text}"'
        self.message = f'syntax error, unexpected {found}'
        if expected:
            self.message += f', expecting "{expected}"'
        super().__init__(self.message)


def tokenize(source, inline):
    pos, line = 0, 1
    if not inline and source.startswith('#!'):
        end = source.find('\n')
        pos, line = (end + 1, 2) if end >= 0 else (len(source), 1)
    while pos < len(source):
        if not inline:
            opening = OPENING.search(source, pos)
            end = opening.start() if opening else len(source)
            text = source[pos:end]
            if text:
                yield Token('text', text, line)
                line += text.count('\n')
            if not opening:
                break
            if opening.group() == '<?=':
                yield Token('name', 'echo', line)
            pos, inline = opening.end(), True
            continue
        match = LEXER.match(source, pos)
        kind, text = match.lastgroup, match.group()
        if kind == 'closing':
            yield Token('symbol', ';', line)
            inline = False
        elif kind not in ('space', 'comment'):
            yield Token(kind, text, line)
        pos, line = match.end(), line + text.count('\n')
    yield Token('eof', '', line)


class Parser:
    precedence = {
        'or': 1, 'xor': 2, 'and': 3,
        '=': 4, '+=': 4, '-=': 4, '*=': 4, '/=': 4, '.=': 4, '%=': 4, '??=': 4,
        '??': 6, '||': 7, '&&': 8, '|': 9, '^': 10, '&': 11,
        '==': 12, '!=': 12, '===': 12, '!==': 12, '<=>': 12,
        '<': 13, '>': 13, '<=': 13, '>=': 13, '.': 14,
        '+': 15, '-': 15, '*': 16, '/': 16, '%': 16, '**': 18,
    }

    def __init__(self, source, inline=False):
        self.tokens = list(tokenize(source, inline))
        self.pos = 0

    @property
    def token(self):
        return self.tokens[self.pos]

    def take(self):
        token = self.token
        if token.kind != 'eof':
            self.pos += 1
        return token

    def accept(self, text):
        if self.token.kind in ('name', 'symbol') and self.token.text.lower() == text:
            self.take()
            return True
        return False

    def expect(self, text):
        if not self.accept(text):
            raise ParseError(self.token, text)

    def program(self):
        result = []
        while self.token.kind != 'eof':
            result.append(self.statement())
        return result

    def body(self):
        if self.accept('{'):
            statements = []
            while not self.accept('}'):
                statements.append(self.statement())
            return statements
        return [self.statement()]

    def statement(self):
        token = self.token
        if token.kind == 'text':
            return ('text', self.take().text)
        if self.accept(';'):
            return ('empty',)
        if token.text == '{':
            return ('block', self.body())
        if self.accept('declare'):
            self.expect('(')
            self.expression()
            self.expect(')')
            return ('block', self.body())
        for keyword in ('echo', 'return', 'yield', 'throw'):
            if self.accept(keyword):
                values = []
                if not self.accept(';'):
                    values.append(self.expression())
                    while keyword == 'echo' and self.accept(','):
                        values.append(self.expression())
                    self.expect(';')
                return (keyword, values)
        for keyword in ('break', 'continue'):
            if self.accept(keyword):
                self.expect(';')
                return (keyword,)
        if self.accept('function'):
            name = self.take().text
            self.expect('(')
            params = []
            if not self.accept(')'):
                while True:
                    self.accept('?')
                    if self.token.kind == 'name':
                        self.take()
                    self.accept('&')
                    if self.token.kind != 'var':
                        raise ParseError(self.token)
                    param = self.take().text
                    default = self.expression() if self.accept('=') else None
                    params.append((param, default))
                    if not self.accept(','):
                        break
                self.expect(')')
            if self.accept(':'):
                self.accept('?')
                if self.token.kind != 'name':
                    raise ParseError(self.token)
                self.take()
            return ('function', name, params, self.body())
        if self.accept('foreach'):
            self.expect('(')
            iterable = self.expression()
            self.expect('as')
            value = self.expression()
            key = value if self.accept('=>') else None
            if key is not None:
                value = self.expression()
            self.expect(')')
            return ('foreach', iterable, key, value, self.body())
        if self.accept('if'):
            return self.conditional()
        if self.accept('while'):
            self.expect('(')
            condition = self.expression()
            self.expect(')')
            return ('while', condition, self.body())
        if self.accept('for'):
            self.expect('(')
            initial = self.sequence(';')
            condition = self.sequence(';')
            after = self.sequence(')')
            return ('for', initial, condition, after, self.body())
        expr = self.expression()
        self.expect(';')
        return ('expr', expr)

    def conditional(self):
        self.expect('(')
        condition = self.expression()
        self.expect(')')
        yes = self.body()
        if self.accept('elseif'):
            no = [self.conditional()]
        else:
            no = self.body() if self.accept('else') else []
        return ('if', condition, yes, no)

    def sequence(self, end):
        result = []
        while not self.accept(end):
            result.append(self.expression())
            if not self.accept(','):
                self.expect(end)
                break
        return result

    def array(self, end):
        items = []
        while not self.accept(end):
            if self.accept(','):
                items.append((None, None))
                continue
            value = self.expression()
            key = value if self.accept('=>') else None
            if key is not None:
                value = self.expression()
            items.append((key, value))
            if not self.accept(','):
                self.expect(end)
                break
        return ('array', items)

    def expression(self, minimum=0):
        left = self.primary()
        while True:
            if self.accept('['):
                index = None if self.accept(']') else self.expression()
                if index is not None:
                    self.expect(']')
                left = ('index', left, index)
            elif self.accept('('):
                left = ('call', left, self.sequence(')'))
            elif self.accept('->') or self.accept('::'):
                name = self.take().text
                left = ('member', left, name)
            elif self.accept('++'):
                left = ('post', left, 1)
            elif self.accept('--'):
                left = ('post', left, -1)
            else:
                break
        while self.token.kind in ('name', 'symbol'):
            op = self.token.text.lower()
            if op == '?' and minimum <= 5:
                yes = None if self.token.text == ':' else self.expression()
                self.expect(':')
                left = ('ternary', left, yes, self.expression(6))
                continue
            level = self.precedence.get(op, -1)
            if level < minimum:
                break
            self.take()
            right = self.expression(level if level == 4 or op in ('??', '**') else level + 1)
            left = ('assign' if level == 4 else 'binary', op, left, right)
        return left

    def primary(self):
        token = self.take()
        kind, text, _ = token
        lower = text.lower()
        if kind == 'var':
            return ('var', text, token.line)
        if kind in ('string', 'number'):
            return (kind, text)
        if kind == 'symbol':
            if text == '[':
                return self.array(']')
            if text == '(':
                casts = ('int', 'integer', 'float', 'double', 'string', 'bool', 'boolean', 'array', 'object')
                if self.token.text.lower() in casts and self.tokens[self.pos + 1].text == ')':
                    cast = self.take().text.lower()
                    self.expect(')')
                    return ('unary', cast, self.expression(17))
                expr = self.expression()
                self.expect(')')
                return expr
            if text in ('+', '-', '!', '~', '@', '++', '--'):
                return ('unary', text, self.expression(17))
        if kind == 'name':
            if lower in ('array', 'list') and self.accept('('):
                return self.array(')')
            if lower == 'new':
                name = self.take().text
                args = self.sequence(')') if self.accept('(') else []
                return ('new', name, args)
            if lower == 'print':
                return ('print', self.expression(4))
            if lower in ('exit', 'die') and self.token.text != '(':
                return ('call', ('name', lower, token.line), [])
            return ('name', text, token.line)
        raise ParseError(token)

