"""Gateway log terminal used by the station's CSV consumers."""
import argparse
import csv
import sqlite3
import sys

from query_catalog import execute, load_export


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("-V", "--version", action="version", version="lnav 0.14.0-8ad2d43")
    parser.add_argument("-n", action="store_true")
    parser.add_argument("-q", action="store_true")
    parser.add_argument("-c", dest="commands", action="append", default=[])
    parser.add_argument("logs", nargs="+")
    args = parser.parse_args()
    try:
        with sqlite3.connect(":memory:") as connection:
            for path in args.logs:
                load_export(connection, path)
            result = None
            for command in args.commands:
                if command.startswith(";"):
                    result = execute(connection, command[1:])
                elif command == ":write-csv-to -" and result is not None and result.description:
                    writer = csv.writer(sys.stdout, lineterminator="\n")
