"""Small C/C++ lexical reader; preserves source coordinates without compiling.

Run: python3 c_tokens.py input.cpp
API: tokenize(text), delimiters(tokens), split_top_level(tokens, separator=',').
Preprocessor tokens are retained; macros and conditional branches are not expanded.
"""
from dataclasses import dataclass, asdict
import json
import re
import sys
from pathlib import Path

@dataclass(frozen=True)
class Token:
    text: str
    kind: str
    offset: int
    end: int
    line: int
    column: int

_PATTERN = re.compile(r'''(?P<space>\s+)|(?P<comment>//[^\n]*|/\*[\s\S]*?\*/)|(?P<string>(?:u8|u|U|L)?"(?:\\[\s\S]|[^"\\])*"|(?:u8|u|U|L)?'(?:\\[\s\S]|[^'\\])*')|(?P<identifier>[A-Za-z_][A-Za-z_0-9]*)|(?P<number>(?:\d|\.\d)[A-Za-z_0-9.]*)|(?P<operator><=>|>>=|<<=|->\*|\.\.\.|::|->|\+\+|--|&&|\|\||==|!=|<=|>=|<<|>>|\+=|-=|\*=|/=|%=|&=|\|=|\^=|##|.)''')
_RAW = re.compile(r'(?:u8|u|U|L)?R"([^ ()\\\t\r\n]{0,16})\(')

def tokenize(source, include_comments=False):
    result = []
    pos, line, column = 0, 1, 1
    while pos < len(source):
        raw = _RAW.match(source, pos)
        if raw:
            terminator = ')' + raw[1] + '"'
            end = source.find(terminator, raw.end())
            if end < 0:
                raise ValueError(f'unterminated raw string at {line}:{column}')
            end += len(terminator)
            text, kind = source[pos:end], 'string'
        else:
            match = _PATTERN.match(source, pos)
            if match is None:
                raise ValueError(f'unrecognized input at {line}:{column}')
            text, kind, end = match[0], match.lastgroup, match.end()
            if source.startswith('/*', pos) and kind != 'comment':
                raise ValueError(f'unterminated comment at {line}:{column}')
        if kind != 'space' and (kind != 'comment' or include_comments):
            result.append(Token(text, kind, pos, end, line, column))
        count = text.count('\n')
        column = len(text.rsplit('\n', 1)[-1]) + 1 if count else column + len(text)
        line += count
        pos = end
    return result

def delimiters(tokens):
    """Return a bidirectional token-index map for (), [] and {}.

    Angle brackets are deliberately excluded: C++ requires syntax context to
    distinguish templates from comparison and shift operators.
    """
    stack, pairs = [], {}
    closers = {')': '(', ']': '[', '}': '{'}
    for index, token in enumerate(tokens):
        if token.kind != 'operator':
            continue
        if token.text in ('(', '[', '{'):
            stack.append((token.text, index))
        elif token.text in closers:
            if not stack or stack[-1][0] != closers[token.text]:
                raise ValueError(f'unmatched {token.text} at {token.line}:{token.column}')
            _, start = stack.pop()
            pairs[start], pairs[index] = index, start
    if stack:
        token = tokens[stack[-1][1]]
        raise ValueError(f'unclosed {token.text} at {token.line}:{token.column}')
    return pairs

def split_top_level(tokens, separator=','):
    pairs = delimiters(tokens)
    start = index = 0
    result = []
    while index < len(tokens):
        if tokens[index].text in ('(', '[', '{') and tokens[index].kind == 'operator':
            index = pairs[index] + 1
            continue
        if tokens[index].text == separator and tokens[index].kind == 'operator':
            result.append(tokens[start:index])
            start = index + 1
        index += 1
    result.append(tokens[start:])
    return result

if __name__ == '__main__':
    for filename in sys.argv[1:]:
        tokens = tokenize(Path(filename).read_text())
        print(json.dumps({'file': filename, 'tokens': [asdict(t) for t in tokens],
                          'delimiters': delimiters(tokens)}, indent=2))

