"""Read and write extended ctags records without parsing a source language.

Run: python3 tag_records.py index.tags
fields is an ordered sequence of (key, value) pairs; bare fields use key ''.
The caller selects fields, language kinds, sorting and pseudo-tag headers.
"""
from dataclasses import dataclass, asdict, field
import json
from pathlib import Path
import sys

@dataclass
class TagRecord:
    name: str
    filename: str
    address: str
    fields: list = field(default_factory=list)

    def render(self):
        items = [self.name, self.filename, self.address + ';"']
        items.extend(key + ':' + str(value) if key else str(value)
                     for key, value in self.fields)
        if any('\t' in item or '\n' in item or '\r' in item for item in items):
            raise ValueError('record fields must not contain literal line or tab delimiters')
        return '\t'.join(items) + '\n'

def search_address(source_line):
    """Encode an anchored forward-search address from one original source line."""
    line = source_line.rstrip('\r\n')
    return '/^' + line.replace('\\', '\\\\').replace('/', '\\/').replace('$', '\\$') + '$/'

def read_records(text):
    records = []
    for line in text.splitlines():
        if not line or line.startswith('!_TAG_'):
            continue
        head = line.split('\t', 2)
        if len(head) != 3 or ';"' not in head[2]:
            raise ValueError('invalid extended tag record: ' + line)
        address, tail = head[2].rsplit(';"', 1)
        fields = []
        for value in tail.removeprefix('\t').split('\t') if tail else []:
            key, sep, data = value.partition(':')
            fields.append((key, data) if sep else ('', key))
        records.append(TagRecord(head[0], head[1], address, fields))
    return records

def render_records(records, sort=True):
    lines = [record.render() for record in records]
    return ''.join(sorted(set(lines), key=lambda s: s.encode('utf-8')) if sort else lines)

if __name__ == '__main__':
    for filename in sys.argv[1:]:
        print(json.dumps([asdict(t) for t in read_records(Path(filename).read_text())], indent=2))

