"""Read a firmware diagnostic intake receipt and verify its recorded source and XML."""
import argparse
from hashlib import sha256
import json
from pathlib import Path
import sys

from diagnostic_records import read_xml


def inspect(receipt_path):
    receipt = json.loads(receipt_path.read_text())
    files = {}
    for name in ("firmware", "diagnostics"):
        record = receipt[name]
        body = (receipt_path.parent / record["path"]).read_bytes()
        if sha256(body).hexdigest() != record["sha256"]:
            raise ValueError(f"{name} digest differs from the receipt: {record['path']}")
        files[name] = body
    findings = read_xml(files["diagnostics"])
    return {"firmware": receipt["firmware"], "diagnostics": receipt["diagnostics"],
            "findings": [{"id": item.id, "symbols": item.symbols} for item in findings]}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("receipt", type=Path)
    args = parser.parse_args()
    try:
        print(json.dumps(inspect(args.receipt), indent=2))
    except (OSError, ValueError) as error:
        sys.exit(str(error))


if __name__ == "__main__":
    main()

