"""Meter diagnostic checks. scan(files, enabled) yields Diagnostic records."""
from pathlib import Path
from c_tokens import delimiters, tokenize
from diagnostic_records import Diagnostic, Location


def unused_functions(files):
    definitions = []
    called = set()
    for filename in files:
        tokens = tokenize(Path(filename).read_text())
        matches = delimiters(tokens)
        depth = 0
        for index, token in enumerate(tokens):
            if token.text == "{":
                depth += 1
            elif token.text == "}":
                depth -= 1
            if token.kind != "identifier" or index + 1 >= len(tokens) or tokens[index + 1].text != "(":
                continue
            after = matches[index + 1] + 1
            if depth == 0 and after < len(tokens) and tokens[after].text == "{":
                definitions.append((filename, token))
            elif depth:
                called.add(token.text)
    for filename, token in definitions:
        if token.text in called or token.text == "main":
            continue
        message = f"The function '{token.text}' is never used."
        yield Diagnostic("unusedFunction", "style", message,
                         [Location(filename, token.line, token.column)], verbose=message,
                         cwe="561", symbols=[token.text])


def scan(files, enabled=("unusedFunction",)):
    if "unusedFunction" in enabled or "all" in enabled:
        yield from unused_functions(files)

