#!/usr/bin/env python3
"""Build the manual archive's public-type XML index from a Doxyfile."""
from dataclasses import dataclass
from pathlib import Path
import re
import shlex
import sys
from xml.sax.saxutils import escape, quoteattr

from c_tokens import tokenize
from doxy_links import member_anchor, enum_value_anchor


@dataclass
class Compound:
    kind: str
    name: str
    ref: str
    members: list


def settings(path):
    options = {}
    for line in path.read_text().splitlines():
        words = shlex.split(line, comments=True)
        if not words:
            continue
        match = re.fullmatch(r'(\w+)\s*(\+?=)\s*(.*)', line.strip())
        if not match:
            raise ValueError('invalid Doxyfile assignment: ' + line)
        key, op, value = match.groups()
        fields = shlex.split(value, comments=True)
        if op == '=':
            options[key] = fields
        else:
            options.setdefault(key, []).extend(fields)
    return options


def public_types(path):
    tokens = [t.text for t in tokenize(path.read_text()) if 'comment' not in t.kind]
    source = ' '.join(tokens)
    namespace = re.fullmatch(r'namespace (\w+) \{ (.*) \}', source)
    if not namespace:
        raise ValueError(f'{path}: expected a namespace of public type declarations')
    name, body = namespace.groups()
    scope = Compound('namespace', name, 'namespace' + name, [])
    structs = []
    while body:
        record = re.match(r'(?:template < (?:typename|class) (\w+) > )?struct (\w+) \{ ([^{}]*) \} ;(?: |$)', body)
        enum = re.match(r'enum class (\w+) \{ ([^{}]*) \} ;(?: |$)', body)
        if record:
            param, short, decls = record.groups()
            qualified = name + '::' + short
            struct = Compound('struct', qualified, 'struct' + name + '_1_1' + short, [])
            for decl in decls.split(';'):
                if not decl.strip():
                    continue
                method = re.fullmatch(r'(\w+) (\w+) \( \)( const)?', decl.strip())
                if not method:
                    raise ValueError(f'{path}: unsupported member declaration {decl}')
                result, method_name, qualifier = method.groups()
                owner = qualified + (f'< {param} >' if param else '')
                anchor = member_anchor(result + ' ' + owner + '::' + method_name,
                                       method_name, '()' + (qualifier or ''))
                struct.members.append(('function', method_name, anchor))
            structs.append(struct)
            body = body[record.end():]
        elif enum:
            member, enumerators = enum.groups()
            anchor = member_anchor(name + '::' + member, member)
            scope.members.append(('enum', member, anchor))
            for value in enumerators.split(','):
                value = value.strip()
                if not value.isidentifier():
                    raise ValueError(f'{path}: unsupported enumerator {value}')
                scope.members.append(('enumvalue', value, enum_value_anchor(anchor, value)))
            body = body[enum.end():]
        else:
            raise ValueError(f'{path}: unsupported declaration {body[:80]}')
    return sorted(structs, key=lambda s: s.name) + [scope, Compound('file', path.name, path.name.replace('.', '_8'), [])]


def index(compounds):
    lines = ["<?xml version='1.0' encoding='UTF-8' standalone='no'?>",
             '<doxygenindex xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:noNamespaceSchemaLocation="index.xsd" version="1.17.0" xml:lang="en-US">']
    for entry in compounds:
        lines.append(f'  <compound refid={quoteattr(entry.ref)} kind={quoteattr(entry.kind)}><name>{escape(entry.name)}</name>')
        for kind, name, anchor in entry.members:
            ref = quoteattr(entry.ref + '_1' + anchor)
            lines.append(f'    <member refid={ref} kind={quoteattr(kind)}><name>{escape(name)}</name></member>')
        lines.append('  </compound>')
    lines.append('</doxygenindex>')
    return '\n'.join(lines) + '\n'


def main():
    if len(sys.argv) != 2:
        sys.exit('usage: doxygen.py DOXYFILE')
    options = settings(Path(sys.argv[1]))
    if options.get('GENERATE_XML') != ['YES'] or options.get('GENERATE_TAGFILE') or options.get('GENERATE_HTML', ['YES']) != ['NO']:
        raise ValueError('archive builder supports the XML index output')
    sources = options.get('INPUT', [])
    if len(sources) != 1:
        raise ValueError('archive builder requires one public header')
    result = index(public_types(Path(sources[0])))
    target = Path(*options.get('OUTPUT_DIRECTORY', [])) / Path(*options.get('XML_OUTPUT', ['xml'])) / 'index.xml'
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(result)


if __name__ == '__main__':
    try:
        main()
    except (ValueError, OSError) as error:
        sys.exit(str(error))

