#!/usr/bin/env python3
"""Read SAM text from the synthetic calibration station.

Run with a SAM path to inspect headers and typed alignment fields as JSON
lines. Raw record text is retained for lossless SAM output. This module does
not implement samtools subcommands, filtering options, BAM/CRAM or reports.
"""
import argparse
import json
from pathlib import Path
import re

FLAGS = dict(zip(('PAIRED','PROPER_PAIR','UNMAP','MUNMAP','REVERSE','MREVERSE',
                  'READ1','READ2','SECONDARY','QCFAIL','DUP','SUPPLEMENTARY'),
                 (1 << bit for bit in range(12))))
CIGAR = re.compile(r'(\d+)([MIDNSHP=X])')
FIELDS = ('qname','flag','rname','pos','mapq','cigar','rnext','pnext','tlen','seq','qual')

def reference_span(cigar):
    if cigar == '*':
        return 0
    parts = CIGAR.findall(cigar)
    if ''.join(n+op for n,op in parts) != cigar or any(int(n) == 0 for n,_ in parts):
        raise ValueError('Invalid CIGAR')
    return sum(int(n) for n,op in parts if op in 'MDN=X')

def parse_line(line):
    raw = line.rstrip('\r\n')
    columns = raw.split('\t')
    if columns[0] in ('@HD','@SQ','@RG','@PG','@CO'):
        return {'kind':'header','record_type':columns[0][1:],'fields':columns[1:],'raw':raw}
    if len(columns) < 11:
        raise ValueError('SAM alignment needs eleven mandatory fields')
    row = dict(zip(FIELDS, columns[:11]))
    for key in ('flag','pos','mapq','pnext','tlen'):
        row[key] = int(row[key])
    if not (0 <= row['flag'] <= 65535 and 0 <= row['mapq'] <= 255 and row['pos'] >= 0):
        raise ValueError('SAM flag, MAPQ or position outside its range')
    span = reference_span(row['cigar'])
    row.update(kind='alignment', tags=columns[11:], raw=raw,
               reference_end=row['pos'] + span - 1 if row['pos'] and span else None)
    return row

def records(path):
    with Path(path).open(encoding='utf-8') as stream:
        for number, line in enumerate(stream, 1):
            if not line.strip():
                continue
            try:
                yield parse_line(line)
            except ValueError as exc:
                raise ValueError(f'{path}:{number}: {exc}') from exc

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('sam')
    args = parser.parse_args()
    for record in records(args.sam):
        print(json.dumps(record, ensure_ascii=False))

