"""Read and write GROMACS coordinate frames in GRO format."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from struct import Struct

_FLOAT = Struct('f')


def real(value):
    """Round a value to the reference build's coordinate precision."""
    return _FLOAT.unpack(_FLOAT.pack(value))[0]


@dataclass(frozen=True)
class Atom:
    resid: int
    resname: str
    name: str
    number: int
    position: tuple
    velocity: tuple | None = None


@dataclass(frozen=True)
class Frame:
    title: str
    atoms: tuple
    box: tuple


def iter_gro(path):
    with Path(path).open() as source:
        for title in source:
            try:
                atom_count = int(source.readline())
                if atom_count < 0:
                    raise ValueError('negative atom count')
                atoms = []
                width = None
                for _ in range(atom_count):
                    line = source.readline().rstrip('\r\n')
                    if width is None:
                        first = line.index('.', 20)
                        width = line.index('.', first + 1) - first
                    end = 20 + 3 * width
                    position = tuple(real(float(line[i:i + width]))
                                     for i in range(20, end, width))
                    velocity = None
                    if line[end:].strip():
                        velocity = tuple(real(float(line[i:i + width]))
                                         for i in range(end, end + 3 * width, width))
                    atoms.append(Atom(int(line[:5]), line[5:10].strip(),
                                      line[10:15].strip(), int(line[15:20]),
                                      position, velocity))
                box = tuple(real(float(part)) for part in source.readline().split())
                if len(box) not in (3, 9):
                    raise ValueError('expected three or nine box components')
            except ValueError as error:
                raise ValueError(f'{path}: invalid GRO frame: {error}') from error
            yield Frame(title.rstrip('\r\n'), tuple(atoms), box)


def read_gro(path):
    frames = iter_gro(path)
    try:
        return next(frames)
    except StopIteration as error:
        raise ValueError(f'{path}: empty GRO file') from error
    finally:
        frames.close()


def box_vectors(box):
    if len(box) == 3:
        box = (*box, 0, 0, 0, 0, 0, 0)
    x, y, z, xy, xz, yx, yz, zx, zy = box
    return ((x, xy, xz), (yx, y, yz), (zx, zy, z))


def write_gro(path, frame):
    has_velocity = any(atom.velocity is not None for atom in frame.atoms)
    lines = [frame.title, f'{len(frame.atoms):5d}']
    for index, atom in enumerate(frame.atoms, 1):
        label = f'{atom.resid % 100000:5d}{atom.resname:<5.5}{atom.name:>5.5}{index % 100000:5d}'
        coords = ''.join(f'{value:8.3f}' for value in atom.position)
        if has_velocity:
            coords += ''.join(f'{value:8.4f}' for value in (atom.velocity or (0, 0, 0)))
        lines.append(label + coords)
    box = frame.box if any(frame.box[3:]) else frame.box[:3]
    lines.append(''.join(f'{value:10.5f}' for value in box))
    Path(path).write_text('\n'.join(lines) + '\n')
